spec.expr:
histogram_quantile(
  0.95,
  sum by (le, service) (
    rate(
      http_request_duration_seconds_bucket{
        service!="",
        handler!~"/(metrics|docs|openapi\\.json|health.*)"
      }[5m]
    )
  )
)

sum(
  rate(
    http_requests_total{
      handler!="/metrics",
      handler!="/docs",
      handler!="/openapi.json",
      handler!="/health",
      handler!="/health/live",
      handler!="/health/ready",
      handler!="/health/startup"
    }[5m]
  )
)

sum(
  rate(
    http_requests_total{
      status=~"5..",
      handler!~"/(metrics|docs|openapi\\.json|health.*)"
    }[5m]
  )
)
/
sum(
  rate(
    http_requests_total{
      handler!~"/(metrics|docs|openapi\\.json|health.*)"
    }[5m]
  )
)
